import type { ZodType } from "zod";
import {
  type BotData,
  BotDataSchema,
  type HttpAuth,
  type TrackerResponseData,
  TrackerResponseSchema,
} from "./types";

async function fetchWithJsonBody(
  url: string,
  options: RequestInit = {},
  body?: unknown,
  segmentUserId?: string,
): Promise<Response> {
  let response: Response;
  try {
    response = await fetch(url, {
      ...options,
      headers: {
        "Content-Type": "application/json",
        "X-User-Id": segmentUserId || "",
        ...(options.headers || {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch (err) {
    let message = "Network error: Unable to reach the server.";
    if (err instanceof Error && err.message) {
      message += `\nDetails: ${err.message}`;
    }
    throw new Error(message);
  }

  if (!response.ok) {
    const errorData: unknown = await response.json().catch(() => ({}));
    let errorMsg = "An unknown API error occurred.";
    if (
      errorData &&
      typeof errorData === "object" &&
      "error" in errorData &&
      typeof (errorData as { error?: string }).error === "string"
    ) {
      errorMsg = (errorData as { error?: string }).error || errorMsg;
    }
    throw new Error(errorMsg);
  }

  return response;
}

export function validateData<T>(data: unknown, schema: ZodType<T>): T {
  const parsed = schema.safeParse(data);
  if (!parsed.success) {
    throw new Error(`Response data validation failed: ${JSON.stringify(parsed.error.issues)}`);
  }
  return parsed.data;
}

const apiRequest = async <TResponse, TRequest = unknown>(
  url: string,
  options: RequestInit = {},
  body?: TRequest,
  responseSchema?: ZodType<TResponse>,
): Promise<TResponse> => {
  const response = await fetchWithJsonBody(url, options, body);
  const data: unknown = await response.json();
  if (responseSchema) {
    return validateData(data, responseSchema);
  }
  return data as TResponse;
};

export const credentialFingerprint = (credential?: string): string => {
  if (!credential) return "none";
  let hash = 5381;
  for (let index = 0; index < credential.length; index++) {
    hash = Math.trunc((hash << 5) + hash + credential.codePointAt(index)!);
  }
  return `${credential.length}:${(hash >>> 0).toString(16)}`;
};

const authorizedGet = (
  endpoint: string,
  httpAuth?: HttpAuth,
): { url: string; options: RequestInit } => {
  const url = new URL(endpoint);
  if (httpAuth?.via === "query") {
    url.searchParams.set("token", httpAuth.token);
  }
  const headers =
    httpAuth?.via === "header" ? { Authorization: `Bearer ${httpAuth.token}` } : undefined;
  return { url: url.toString(), options: { method: "GET", ...(headers && { headers }) } };
};

export const getBotData = async ({
  projectUrl,
  botDataEndpoint,
  httpAuth,
}: {
  projectUrl: string;
  botDataEndpoint: string;
  httpAuth?: HttpAuth;
}): Promise<BotData> => {
  const { url, options } = authorizedGet(`${projectUrl}${botDataEndpoint}`, httpAuth);
  return apiRequest<BotData>(url, options, undefined, BotDataSchema);
};

export const getConversationHistory = async ({
  projectUrl,
  trackerEndpoint,
  httpAuth,
}: {
  projectUrl: string;
  trackerEndpoint: string;
  httpAuth?: HttpAuth;
}): Promise<TrackerResponseData> => {
  const { url, options } = authorizedGet(`${projectUrl}${trackerEndpoint}`, httpAuth);
  return apiRequest<TrackerResponseData>(url, options, undefined, TrackerResponseSchema);
};
